@php
    // Every image path is server-generated by an authenticated upload; URLs
    // are never taken from a visitor's Host or query-string parameters.
    $background = $options['login_background'] ? asset('public/storage/' . $options['login_background']) : null;
    $favicon = $options['favicon'] ? asset('public/storage/' . $options['favicon']) : null;
    $logo = $options['logo'] ? asset('public/storage/' . $options['logo']) : null;
    $slides = [];
    foreach (($options['slides'] ?? []) as $slide) {
        if (! empty($slide['title']) && ! empty($slide['image'])) {
            $slides[] = [
                'title' => (string) $slide['title'],
                'caption' => (string) ($slide['caption'] ?? ''),
                'image' => asset('public/storage/' . $slide['image']),
            ];
        }
    }
@endphp
@if ($favicon)
<link rel="icon" href="{{ $favicon }}" type="image/png" id="lcc-theme-login-favicon">
@endif
<style id="lcc-theme-public-login">
@if ($background)
#app {
    background-image: url("{{ $background }}") !important;
    background-size: cover !important;
    background-position: center center !important;
}
@endif
@if (! $options['login_slider'])
#app .swiper { display: none !important; }
@endif
</style>

@if ($logo || $slides)
<script id="lcc-theme-public-login-script">
(function () {
    const logo = @json($logo);
    const name = @json($options['brand_name'] ?: 'Company');
    const slides = @json($slides);
    function applyLoginTheme() {
        if (logo) {
            const original = document.querySelector('#app img[src*="akaunting-logo"]');
            if (original) {
                original.src = logo;
                original.alt = name;
                original.classList.add('lcc-theme-login-logo');
                original.style.cssText = 'height:3.5rem;width:auto;max-width:12rem;object-fit:contain;';
            }
        }
        if (!slides.length) return;
        const container = document.querySelector('#app .swiper-container');
        const wrapper = container?.querySelector('.swiper-wrapper');
        if (!container || !wrapper) return;

        // Build DOM exclusively through textContent and safe image URLs from
        // the application's own public filesystem, not untrusted HTML.
        const nodes = slides.map(function (slide) {
            const panel = document.createElement('div');
            panel.className = 'swiper-slide flex justify-center flex-col items-center';
            const imageFrame = document.createElement('div');
            imageFrame.style.cssText = 'width:min(450px,90%);height:300px;';
            const image = document.createElement('img');
            image.src = slide.image;
            image.alt = slide.title;
            image.style.cssText = 'max-width:100%;max-height:100%;object-fit:contain;';
            imageFrame.appendChild(image);
            panel.appendChild(imageFrame);
            const title = document.createElement('h1');
            title.className = 'text-3xl text-black-400 font-bold';
            title.textContent = slide.title;
            panel.appendChild(title);
            if (slide.caption) {
                const caption = document.createElement('p');
                caption.className = 'text-base text-black-400 mt-2 text-center';
                caption.textContent = slide.caption;
                panel.appendChild(caption);
            }
            return panel;
        });

        if (container.swiper) {
            const swiper = container.swiper;
            swiper.removeAllSlides();
            nodes.forEach(function (node) { swiper.appendSlide(node.outerHTML); });
            swiper.slideTo(0, 0);
            swiper.update();
        } else {
            wrapper.replaceChildren(...nodes);
        }
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', applyLoginTheme, {once: true});
    } else {
        applyLoginTheme();
    }
})();
</script>
@endif
